use super::*;
use crate::{temporal::Engine,Command};
fn room()->Run {let mut r=crate::storage::deserialize(include_str!("../../../../fixtures/avatar-room-v1.json")).unwrap();r.simulation_revision=52.0.into();r.player.abilities=vec![ID.into()];r.player.active.clear();r.player.conditions.clear();r.player.hp=100.;r.player.max_hp=100.;r.player.energy=40.;r.player.stats.max_energy=100.;r.inventory.clear();for g in r.ground.values_mut(){std::sync::Arc::make_mut(g).clear();}r.offers.clear();r.history.clear();r.replay.clear();r.haste_snapshot=Field::Missing;r.future=None;for actors in r.actors.values_mut(){std::sync::Arc::make_mut(actors).clear();}r}
fn activate()->Command {Command::Ability{id:ID.into(),target:Field::Missing,x:Field::Missing,y:Field::Missing}}
#[test] fn manual_restores_floor_entry_without_payment_and_is_once_per_floor(){let mut e=Engine::new(room()).unwrap();let original=e.run.clone();e.run.player.hp=20.;e.run.player.energy=3.;e.run.tick+=7.;e.dispatch(&activate()).unwrap();assert_eq!(e.run.player.hp,original.player.hp);assert_eq!(e.run.player.energy,original.player.energy);assert_eq!(e.run.tick,original.tick);assert!(used(&e.run,e.run.depth));e.run.player.hp=21.;e.dispatch(&activate()).unwrap();assert_eq!(e.run.player.hp,21.);}
#[test] fn spent_ledger_survives_save_load_and_reentry(){let mut e=Engine::new(room()).unwrap();e.dispatch(&activate()).unwrap();let mut e=Engine::load(&e.save().unwrap()).unwrap();assert!(used(&e.run,1.));capture_entry(&mut e.run).unwrap();assert!(!available(&e.run));assert!(e.run.future_floor.as_ref().unwrap().anchor.is_none());}
#[test] fn new_floor_captures_fresh_but_keeps_old_spent_floors(){let mut e=Engine::new(room()).unwrap();e.dispatch(&activate()).unwrap();e.run.depth=2.;capture_entry(&mut e.run).unwrap();assert!(used(&e.run,1.));assert!(!used(&e.run,2.));assert!(available(&e.run));}
#[test] fn anchor_has_no_recursive_floor_anchor(){let e=Engine::new(room()).unwrap();let anchor=e.run.future_floor.as_ref().unwrap().anchor.as_ref().unwrap();assert!(anchor.native_state().unwrap().future_floor.is_none());let restored=Engine::load(&e.save().unwrap()).unwrap();assert!(available(&restored.run));}
#[test] fn lethal_turn_restores_then_second_death_is_terminal(){let mut e=Engine::new(room()).unwrap();e.run.player.hp=1.;e.run.player.conditions.insert("poisoned".into(),5.);e.dispatch(&Command::Wait).unwrap();assert_eq!(e.run.status,"playing");assert_eq!(e.run.player.hp,100.);assert!(used(&e.run,1.));assert!(!e.run.player.conditions.contains_key("poisoned"));e.run.player.hp=1.;e.run.player.conditions.insert("poisoned".into(),5.);e.dispatch(&Command::Wait).unwrap();assert_eq!(e.run.status,"dead");}
#[test] fn lethal_turn_without_ability_does_not_rewind(){let mut r=room();r.player.abilities.clear();let mut e=Engine::new(r).unwrap();e.run.player.hp=1.;e.run.player.conditions.insert("poisoned".into(),5.);e.dispatch(&Command::Wait).unwrap();assert_eq!(e.run.status,"dead");assert!(!used(&e.run,1.));}
#[test] fn save_load_preserves_original_entry_not_loaded_position(){let mut e=Engine::new(room()).unwrap();let hp=e.run.player.hp;let energy=e.run.player.energy;e.run.player.hp=17.;e.run.player.energy=2.;let mut e=Engine::load(&e.save().unwrap()).unwrap();e.dispatch(&activate()).unwrap();assert_eq!(e.run.player.hp,hp);assert_eq!(e.run.player.energy,energy);}
#[test] fn legacy_replay_keeps_old_paid_anchor(){let mut r=room();r.future_floor_rules_from=Field::Null;let mut e=Engine::new(r).unwrap();e.dispatch(&activate()).unwrap();assert!(e.run.future.is_some());assert!(e.run.future_floor.is_none());assert_eq!(e.run.player.energy,0.);}
#[test] fn actual_floor_travel_replaces_entry_and_revisit_stays_spent(){let mut e=Engine::new(room()).unwrap();e.dispatch(&activate()).unwrap();assert!(crate::travel::travel(&mut e.run,1.,false,false).unwrap());assert_eq!(e.run.depth,2.);let entry=e.run.future_floor.as_ref().unwrap().anchor.as_ref().unwrap().native_state().unwrap().player.clone();e.run.player.hp=2.;e.dispatch(&activate()).unwrap();assert_eq!(e.run.player.hp,entry.hp);assert!(used(&e.run,1.)&&used(&e.run,2.));assert!(crate::travel::travel(&mut e.run,-1.,false,false).unwrap());assert!(!available(&e.run));}
